// Groove Glimmer — Live Preview Embed Script
// Include in your site's <head> to enable live theme preview from the editor.
(function () {
	"use strict";
	if (window.grooveEmbed) return;

	// ----- CONFIGURATION -----
	const ALLOWED_ORIGINS = ["https://your-domain.com", "http://localhost:3000"];

	const DEFAULT_FONT_WEIGHTS = ["400", "500", "600", "700"];

	const SYSTEM_FONTS = [
		"ui-sans-serif", "ui-serif", "ui-monospace", "system-ui",
		"sans-serif", "serif", "monospace", "cursive", "fantasy",
	];

	const MSG = {
		PING: "GROOVE_PING",
		PONG: "GROOVE_PONG",
		COLLECT_VARS: "GROOVE_COLLECT_VARS",
		VARS_RESPONSE: "GROOVE_VARS_RESPONSE",
		VAR_UPDATE: "GROOVE_VAR_UPDATE",
		VAR_UPDATE_BATCH: "GROOVE_VAR_UPDATE_BATCH",
		NAVIGATION_UPDATE: "GROOVE_NAVIGATION_UPDATE",
		EMBED_LOADED: "GROOVE_EMBED_LOADED",
		EMBED_ERROR: "GROOVE_EMBED_ERROR",
	};

	// ----- MESSAGE SENDING -----
	function sendToParent(msg) {
		if (window.parent && window.parent !== window) {
			try {
				window.parent.postMessage(msg, "*");
			} catch (e) {
				console.warn("Groove Embed: Failed to send message:", e);
			}
		}
	}

	// ----- ORIGIN VALIDATION -----
	function isOriginAllowed(origin) {
		if (ALLOWED_ORIGINS.indexOf(origin) !== -1) return true;
		try {
			var url = new URL(origin);
			return url.hostname === "localhost";
		} catch (e) {
			return false;
		}
	}

	// ----- VARIABLE COLLECTION -----
	function collectVariables() {
		var styles = getComputedStyle(document.documentElement);
		var variables = {};
		for (var i = 0; i < styles.length; i++) {
			var prop = styles[i];
			if (prop.startsWith("--")) {
				var val = styles.getPropertyValue(prop).trim();
				if (val) variables[prop] = val;
			}
		}
		return variables;
	}

	// ----- VARIABLE APPLICATION -----
	function applyVariable(name, value) {
		if (typeof name === "string" && name.startsWith("--") && typeof value === "string") {
			document.documentElement.style.setProperty(name, value);
		}
	}

	// ----- DARK MODE CLASS -----
	function updateDarkModeClass() {
		var mode = document.documentElement.style.getPropertyValue("--mode");
		if (!mode) {
			// Also check if the parent set a mode variable
			mode = getComputedStyle(document.documentElement).getPropertyValue("--mode").trim();
		}
		if (mode === "dark") {
			document.documentElement.classList.add("dark");
		} else if (mode === "light") {
			document.documentElement.classList.remove("dark");
		}
	}

	// ----- FONT LOADING -----
	function extractFontFamily(fontFamilyValue) {
		if (!fontFamilyValue) return null;
		var firstFont = fontFamilyValue.split(",")[0].trim().replace(/['"]/g, "");
		if (SYSTEM_FONTS.indexOf(firstFont.toLowerCase()) !== -1) return null;
		return firstFont;
	}

	function loadGoogleFont(family, weights) {
		weights = weights || DEFAULT_FONT_WEIGHTS;
		var encodedFamily = encodeURIComponent(family);
		var weightsParam = weights.join(";");
		var href = "https://fonts.googleapis.com/css2?family=" + encodedFamily + ":wght@" + weightsParam + "&display=swap";

		if (document.querySelector('link[href="' + href + '"]')) return;

		var link = document.createElement("link");
		link.rel = "stylesheet";
		link.href = href;
		document.head.appendChild(link);
	}

	function overrideFontClasses(fonts) {
		var styleId = "groove-font-overrides";
		var styleEl = document.getElementById(styleId);
		if (!styleEl) {
			styleEl = document.createElement("style");
			styleEl.id = styleId;
			document.head.appendChild(styleEl);
		}

		var rules = [];
		if (fonts.sans) rules.push(".font-sans { font-family: " + fonts.sans + " !important; }");
		if (fonts.serif) rules.push(".font-serif { font-family: " + fonts.serif + " !important; }");
		if (fonts.mono) rules.push(".font-mono { font-family: " + fonts.mono + " !important; }");
		styleEl.textContent = rules.join("\n");
	}

	function handleFontUpdate(name, value) {
		if (name !== "--font-sans" && name !== "--font-serif" && name !== "--font-mono") return;
		var fonts = {
			sans: getComputedStyle(document.documentElement).getPropertyValue("--font-sans").trim() || null,
			serif: getComputedStyle(document.documentElement).getPropertyValue("--font-serif").trim() || null,
			mono: getComputedStyle(document.documentElement).getPropertyValue("--font-mono").trim() || null,
		};
		Object.entries(fonts).forEach(function (entry) {
			var fontFamily = extractFontFamily(entry[1]);
			if (fontFamily) loadGoogleFont(fontFamily, DEFAULT_FONT_WEIGHTS);
		});
		overrideFontClasses(fonts);
	}

	// ----- SHADOW CLASS OVERRIDES -----
	function overrideShadowClasses() {
		var styleId = "groove-shadow-overrides";
		var styleEl = document.getElementById(styleId);
		if (!styleEl) {
			styleEl = document.createElement("style");
			styleEl.id = styleId;
			document.head.appendChild(styleEl);
		}

		var cs = getComputedStyle(document.documentElement);
		var shadowColor = cs.getPropertyValue("--shadow-color").trim();
		var offsetX = cs.getPropertyValue("--shadow-offset-x").trim();
		var offsetY = cs.getPropertyValue("--shadow-offset-y").trim();
		var blur = cs.getPropertyValue("--shadow-blur").trim();
		var spread = cs.getPropertyValue("--shadow-spread").trim();
		var opacity = parseFloat(cs.getPropertyValue("--shadow-opacity").trim()) || 0.1;

		if (!shadowColor && !offsetX && !offsetY && !blur) {
			styleEl.textContent = "";
			return;
		}

		var colorMix = function (mult) {
			return "color-mix(in srgb, " + shadowColor + " calc(" + (opacity * mult) + " * 100%), transparent)";
		};

		var secondLayer = function (fy, fb) {
			var s2 = (parseFloat(spread.replace("px", "") || "0") - 1) + "px";
			return offsetX + " " + fy + " " + fb + " " + s2 + " " + colorMix(1);
		};

		var rules = [
			".shadow-2xs { box-shadow: " + offsetX + " " + offsetY + " " + blur + " " + spread + " " + colorMix(0.5) + "; }",
			".shadow-xs { box-shadow: " + offsetX + " " + offsetY + " " + blur + " " + spread + " " + colorMix(0.5) + "; }",
			".shadow-sm { box-shadow: " + offsetX + " " + offsetY + " " + blur + " " + spread + " " + colorMix(1) + ", " + secondLayer("1px", "2px") + "; }",
			".shadow { box-shadow: " + offsetX + " " + offsetY + " " + blur + " " + spread + " " + colorMix(1) + ", " + secondLayer("1px", "2px") + "; }",
			".shadow-md { box-shadow: " + offsetX + " " + offsetY + " " + blur + " " + spread + " " + colorMix(1) + ", " + secondLayer("2px", "4px") + "; }",
			".shadow-lg { box-shadow: " + offsetX + " " + offsetY + " " + blur + " " + spread + " " + colorMix(1) + ", " + secondLayer("4px", "6px") + "; }",
			".shadow-xl { box-shadow: " + offsetX + " " + offsetY + " " + blur + " " + spread + " " + colorMix(1) + ", " + secondLayer("8px", "10px") + "; }",
			".shadow-2xl { box-shadow: " + offsetX + " " + offsetY + " " + blur + " " + spread + " " + colorMix(2.5) + "; }",
		];

		styleEl.textContent = rules.join("\n");
	}

	// ----- NAVIGATION TRACKING -----
	function emitNavigationUpdate() {
		try {
			sendToParent({ type: MSG.NAVIGATION_UPDATE, payload: { url: window.location.href } });
		} catch (e) {
			// noop
		}
	}

	function patchHistory() {
		var originalPushState = history.pushState;
		var originalReplaceState = history.replaceState;

		history.pushState = function () {
			var ret = originalPushState.apply(this, arguments);
			emitNavigationUpdate();
			return ret;
		};

		history.replaceState = function () {
			var ret = originalReplaceState.apply(this, arguments);
			emitNavigationUpdate();
			return ret;
		};
	}

	// ----- MESSAGE HANDLER -----
	function handleMessage(event) {
		if (event.source !== window.parent) return;
		if (!event.data || typeof event.data.type !== "string") return;

		if (!isOriginAllowed(event.origin)) {
			sendToParent({
				type: MSG.EMBED_ERROR,
				payload: { error: "Origin not allowed. Preview failed to establish the connection." },
			});
			return;
		}

		var type = event.data.type;
		var payload = event.data.payload;

		switch (type) {
			case MSG.PING:
				sendToParent({ type: MSG.PONG });
				break;

			case MSG.COLLECT_VARS:
				var vars = collectVariables();
				sendToParent({ type: MSG.VARS_RESPONSE, payload: { variables: vars } });
				break;

			case MSG.VAR_UPDATE:
				if (payload && payload.name && payload.value !== undefined) {
					applyVariable(payload.name, payload.value);
					updateDarkModeClass();
					handleFontUpdate(payload.name, payload.value);
					if (payload.name.startsWith("--shadow-")) {
						overrideShadowClasses();
					}
				}
				break;

			case MSG.VAR_UPDATE_BATCH:
				if (payload && payload.variables) {
					Object.entries(payload.variables).forEach(function (entry) {
						applyVariable(entry[0], entry[1]);
					});
					updateDarkModeClass();
					overrideShadowClasses();
				}
				break;
		}
	}

	// ----- INITIALIZATION -----
	window.addEventListener("message", handleMessage);

	try {
		patchHistory();
	} catch (e) {
		// noop
	}
	window.addEventListener("popstate", emitNavigationUpdate);
	window.addEventListener("hashchange", emitNavigationUpdate);

	window.grooveEmbed = {
		initialized: true,
		version: "1.0.0",
		destroy: function () {
			window.removeEventListener("message", handleMessage);
			window.removeEventListener("popstate", emitNavigationUpdate);
			window.removeEventListener("hashchange", emitNavigationUpdate);
			delete window.grooveEmbed;
		},
	};

	sendToParent({ type: MSG.EMBED_LOADED });
	emitNavigationUpdate();
})();
